CREATE TABLE IF NOT EXISTS schema_migrations (version TEXT PRIMARY KEY);
CREATE TABLE IF NOT EXISTS organizations (id TEXT PRIMARY KEY, name TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS patients (id TEXT PRIMARY KEY, healthpass_id TEXT UNIQUE NOT NULL, name TEXT NOT NULL, dob TEXT, phone TEXT, sex TEXT NOT NULL DEFAULT 'unknown', emergency_contact TEXT NOT NULL DEFAULT '', allergy_status TEXT NOT NULL DEFAULT 'unknown', allergies TEXT NOT NULL DEFAULT '', created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS users (id TEXT PRIMARY KEY, email TEXT UNIQUE NOT NULL, name TEXT NOT NULL, password_hash TEXT NOT NULL, patient_id TEXT REFERENCES patients(id), verified INTEGER NOT NULL DEFAULT 0, active INTEGER NOT NULL DEFAULT 1, totp_secret TEXT, pending_totp TEXT, last_totp_step TEXT);
CREATE TABLE IF NOT EXISTS memberships (id TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id), organization_id TEXT NOT NULL REFERENCES organizations(id), role TEXT NOT NULL CHECK(role IN ('clinician','reception','administrator')), active INTEGER NOT NULL DEFAULT 1, UNIQUE(user_id,organization_id));
CREATE TABLE IF NOT EXISTS patient_links (patient_id TEXT NOT NULL REFERENCES patients(id), organization_id TEXT NOT NULL REFERENCES organizations(id), created_at TEXT NOT NULL, PRIMARY KEY(patient_id,organization_id));
CREATE TABLE IF NOT EXISTS consents (id TEXT PRIMARY KEY, patient_id TEXT NOT NULL REFERENCES patients(id), recipient_id TEXT NOT NULL REFERENCES organizations(id), grantor_id TEXT NOT NULL REFERENCES users(id), purpose TEXT NOT NULL, expires_at TEXT NOT NULL, revoked_at TEXT, created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS sessions (id TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id), token_hash TEXT UNIQUE NOT NULL, organization_id TEXT REFERENCES organizations(id), mfa_verified INTEGER NOT NULL DEFAULT 0, expires_at TEXT NOT NULL, created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS encounters (id TEXT PRIMARY KEY, patient_id TEXT NOT NULL REFERENCES patients(id), organization_id TEXT NOT NULL REFERENCES organizations(id), author_id TEXT NOT NULL REFERENCES users(id), status TEXT NOT NULL CHECK(status IN ('draft','signed','amended')), version INTEGER NOT NULL DEFAULT 1, complaint TEXT NOT NULL DEFAULT '', history TEXT NOT NULL DEFAULT '', findings TEXT NOT NULL DEFAULT '', assessment TEXT NOT NULL DEFAULT '', plan TEXT NOT NULL DEFAULT '', created_at TEXT NOT NULL, updated_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS note_versions (id TEXT PRIMARY KEY, encounter_id TEXT NOT NULL REFERENCES encounters(id), version INTEGER NOT NULL, author_id TEXT NOT NULL REFERENCES users(id), payload TEXT NOT NULL, signature_hash TEXT NOT NULL, signed_at TEXT NOT NULL, amendment_reason TEXT, previous_id TEXT REFERENCES note_versions(id), UNIQUE(encounter_id,version));
CREATE TABLE IF NOT EXISTS audits (id TEXT PRIMARY KEY, actor_id TEXT REFERENCES users(id), organization_id TEXT REFERENCES organizations(id), patient_id TEXT REFERENCES patients(id), resource_id TEXT, action TEXT NOT NULL, decision TEXT NOT NULL CHECK(decision IN ('allow','deny')), purpose TEXT NOT NULL, consent_id TEXT REFERENCES consents(id), created_at TEXT NOT NULL, correlation_id TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS encounter_patient_org ON encounters(patient_id, organization_id);
CREATE INDEX IF NOT EXISTS consent_scope ON consents(patient_id, recipient_id, expires_at);
CREATE INDEX IF NOT EXISTS audit_scope ON audits(patient_id, organization_id, created_at);
CREATE INDEX IF NOT EXISTS session_expiry ON sessions(expires_at);
